import { writeFile } from "node:fs/promises";
import { scanGraph } from "../backend/src/graph/scan";
import { measure } from "../backend/src/coverage/metrics";
import { hash } from "../backend/src/git/local";
import type { Snapshot } from "../packages/contracts/src/index";

// Supplement #22 with explicit graph/coverage vectors, generated by the retained Node reference.
const texts = {
  "tsconfig.json":
    '{"compilerOptions":{"baseUrl":".","paths":{"@app/*":["src/*"]}}}',
  "src/a.ts":
    "import { b } from '@app/b';\nexport function a(x: number) { if (x) return b(); return 0; }\n",
  "src/b.ts": "import { a } from './a'; export function b() { return a(0); }\n",
  "src/Bad.ts": "export function broken( {",
  "src/A.java":
    "package demo; import java.util.List; class A { B b; List<String> names; }",
  "src/B.java": "package demo; class B { A a; }",
};
const entries = Object.keys(texts)
  .sort()
  .map((name) => ({ path: name, mode: "100644", oid: "a".repeat(40) }));
const inventory = { complete: true, entries };
const snapshot = {
  id: "analysis-fixture",
  sessionId: "session-analysis",
  root: "/fixture",
  head: "abc",
  capturedAt: "2026-01-01T00:00:00.000Z",
  graphContext: { before: inventory, after: inventory },
  files: Object.entries(texts).map(([name, text], index) => ({
    id: `file-${index}`,
    fingerprint: hash(text),
    path: name,
    oldPath: name,
    status: "modified",
    before: { kind: "text", text },
    after: { kind: "text", text },
  })),
} as unknown as Snapshot;
const source = (side: "before" | "after") => ({
  paths: entries.map((e) => e.path),
  complete: true,
  revision: hash(
    JSON.stringify([
      snapshot.graphContext![side],
      snapshot.files.map((f) => [f.id, f.fingerprint]),
      side,
    ]),
  ),
  read: async (name: string) => texts[name as keyof typeof texts],
});
const graphs = [];
for (const options of [
  { side: "after" as const, maxFiles: 10000, maxBytes: 20 * 1024 * 1024 },
  { side: "before" as const, maxFiles: 2, maxBytes: 1024 },
]) {
  const graph = await scanGraph(
    snapshot,
    options,
    undefined,
    source(options.side),
  );
  graph.capturedAt = "<timestamp>";
  graphs.push(graph);
}
const report = JSON.stringify({
  "src/a.ts": {
    statementMap: {
      "0": { start: { line: 2, column: 31 }, end: { line: 2, column: 51 } },
      "1": { start: { line: 2, column: 52 }, end: { line: 2, column: 61 } },
    },
    s: { "0": 1, "1": 0 },
  },
});
const javaReport =
  '<!DOCTYPE report PUBLIC "-//JACOCO//DTD Report 1.1//EN" "report.dtd"><report><package name="demo"><class name="demo/A" sourcefilename="A.java"><method name="work" desc="()V" line="1"><counter type="COMPLEXITY" missed="1" covered="2"/><counter type="INSTRUCTION" missed="1" covered="3"/></method></class></package></report>';
const coverage = [];
for (const format of ["istanbul", "jacoco"] as const)
  for (const aligned of [false, true]) {
    const raw = format === "istanbul" ? report : javaReport;
    const provenance = aligned
      ? {
          version: 1,
          reportHash: hash(raw),
          sourceHashes: Object.fromEntries(
            Object.entries(texts).map(([name, text]) => [name, hash(text)]),
          ),
          head: "abc",
          tool: "fixture",
          capturedAt: "2026-01-01",
        }
      : null;
    const metrics = measure(snapshot, format, raw, provenance);
    metrics.capturedAt = "<timestamp>";
    coverage.push({ format, report: raw, provenance, metrics });
  }
await writeFile(
  "tests/fixtures/java-analysis.json",
  JSON.stringify({ snapshot, graphs, coverage }, null, 2) + "\n",
);
